if mibBuilder.loadTexts: cdxUpInfoElemStatsEntry.setReference('Data-Over-Cable Service Interface Specifications (DOCSIS)\n             Radio Frequency Interface Specification (SP-RFI-I05-000714)\n             section 7.1.2')
